mapper.update:

	update CHB_EQU_SUB  sub
	set
	sub.HOLDER_TYPE = #{item.holderType,jdbcType=VARCHAR}
	where
	sub.INDENTIFY_MARK = #{item.indentifyMark}
	AND SUBMIT_STATUS='01'

;


    update CHB_EQU_HOLD  sub
    set
    sub.HOLDER_TYPE = #{item.holderType,jdbcType=VARCHAR}
    where
    sub.INDENTIFY_MARK = #{item.indentifyMark}
    AND STATUS='E'

;
